-- Catalog tables, seeds (format 1) and migration store bootstrap from 54f188a5.
CREATE SCHEMA multigres;

CREATE TYPE multigres.shard_ref AS (
	database TEXT,
	table_group TEXT,
	shard TEXT
);

-- catalog-only boundary
CREATE TABLE IF NOT EXISTS multigres.catalog_state (
	singleton       boolean PRIMARY KEY DEFAULT true CHECK (singleton),
	format_version  integer NOT NULL,
	routing_version bigint  NOT NULL DEFAULT 0,
	plan_epoch      bigint  NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS multigres.tablegroup (
	tablegroup_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
	name          text NOT NULL UNIQUE,
	state         text NOT NULL CHECK (state IN ('creating', 'active', 'dropping')),
	created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS multigres.shard (
	shard_id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
	tablegroup_id bigint NOT NULL REFERENCES multigres.tablegroup (tablegroup_id),
	shard_name    text   NOT NULL,
	range_start   bytea,
	range_end     bytea,
	state         text   NOT NULL CHECK (state IN ('preparing', 'active', 'retired')),
	UNIQUE (tablegroup_id, shard_name)
);

CREATE TABLE IF NOT EXISTS multigres.tablegroup_table (
	table_id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
	schema_name   text   NOT NULL,
	table_name    text   NOT NULL,
	tablegroup_id bigint NOT NULL REFERENCES multigres.tablegroup (tablegroup_id),
	UNIQUE (schema_name, table_name)
);

CREATE TABLE IF NOT EXISTS multigres.shard_index (
	shard_index_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
	name           text  NOT NULL UNIQUE,
	type           text  NOT NULL,
	params         jsonb NOT NULL DEFAULT '{}',
	state          text  NOT NULL CHECK (state IN ('preparing', 'active', 'retired'))
);

CREATE TABLE IF NOT EXISTS multigres.shard_key (
	shard_key_id   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
	table_id       bigint NOT NULL REFERENCES multigres.tablegroup_table (table_id),
	shard_index_id bigint NOT NULL REFERENCES multigres.shard_index (shard_index_id),
	name           text   NOT NULL,
	role           text   NOT NULL CHECK (role IN ('primary', 'secondary')),
	state          text   NOT NULL CHECK (state IN ('preparing', 'active', 'retired')),
	UNIQUE (table_id, name)
);

CREATE UNIQUE INDEX IF NOT EXISTS shard_key_one_active_primary
	ON multigres.shard_key (table_id) WHERE role = 'primary' AND state = 'active';

CREATE TABLE IF NOT EXISTS multigres.shard_key_column (
	shard_key_id bigint  NOT NULL REFERENCES multigres.shard_key (shard_key_id),
	position     integer NOT NULL,
	column_name  text    NOT NULL,
	PRIMARY KEY (shard_key_id, position)
);

CREATE TABLE IF NOT EXISTS multigres.operation (
	operation_id     uuid PRIMARY KEY,
	kind             text NOT NULL,
	state            text NOT NULL,
	request          jsonb NOT NULL DEFAULT '{}',
	initiating_role  text,
	cancel_requested boolean NOT NULL DEFAULT false,
	last_error       text,
	created_at       timestamptz NOT NULL DEFAULT now(),
	updated_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS multigres.connections (
	connection_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	name          text NOT NULL UNIQUE,
	dsn           text NOT NULL,
	owner_role    text NOT NULL DEFAULT '',
	created_at    timestamptz NOT NULL DEFAULT now()
);

INSERT INTO multigres.catalog_state (format_version) VALUES (0) ON CONFLICT (singleton) DO NOTHING;

INSERT INTO multigres.tablegroup (name, state)
	SELECT 'default', 'active'
	WHERE NOT EXISTS (SELECT 1 FROM multigres.tablegroup WHERE name = 'default')
	ON CONFLICT (name) DO NOTHING;

INSERT INTO multigres.shard (tablegroup_id, shard_name, state)
	SELECT tg.tablegroup_id, '0-inf', 'active' FROM multigres.tablegroup tg
	WHERE tg.name = 'default'
	  AND NOT EXISTS (SELECT 1 FROM multigres.shard s WHERE s.tablegroup_id = tg.tablegroup_id AND s.shard_name = '0-inf')
	ON CONFLICT (tablegroup_id, shard_name) DO NOTHING;

UPDATE multigres.catalog_state SET format_version = 1;

-- catalog-only boundary
CREATE TABLE IF NOT EXISTS multigres.migration (
	migration_id BIGINT PRIMARY KEY,
	migration_name TEXT NULL,
	created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
	migration_phase TEXT NOT NULL,
	migration_target multigres.shard_ref NOT NULL,
	connection_id BIGINT NOT NULL,
	sequence_margin BIGINT NOT NULL DEFAULT 0,
	copy_data BOOLEAN NOT NULL DEFAULT true,
	skip_schema_copy BOOLEAN NOT NULL DEFAULT false,
	direction TEXT NOT NULL DEFAULT 'IMPORT',
	last_error TEXT NOT NULL DEFAULT '',
	reverse_link_error TEXT NOT NULL DEFAULT '',
	streaming_since TIMESTAMPTZ NULL
);

CREATE TABLE IF NOT EXISTS multigres.migration_tables (
	migration_id BIGINT NOT NULL REFERENCES multigres.migration(migration_id) ON DELETE CASCADE,
	schema_name TEXT NOT NULL,
	table_name TEXT NOT NULL,
	PRIMARY KEY (migration_id, schema_name, table_name)
);

CREATE TABLE IF NOT EXISTS multigres.migration_journal (
	seq BIGSERIAL PRIMARY KEY,
	migration_id BIGINT NOT NULL,
	migration_name TEXT NOT NULL DEFAULT '',
	event TEXT NOT NULL,
	phase TEXT NOT NULL,
	direction TEXT NOT NULL,
	from_lsn TEXT NOT NULL DEFAULT '',
	to_lsn TEXT NOT NULL DEFAULT '',
	last_error TEXT NOT NULL DEFAULT '',
	detail TEXT NOT NULL DEFAULT '',
	created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS migration_name_key
	ON multigres.migration (migration_name) WHERE migration_name IS NOT NULL;

CREATE INDEX IF NOT EXISTS migration_journal_migration_id_idx
	ON multigres.migration_journal (migration_id, seq);

-- catalog-only boundary
DO $fk$
BEGIN
	IF NOT EXISTS (
		SELECT 1 FROM pg_constraint
		WHERE contype = 'f'
		  AND conrelid = to_regclass('multigres.migration')
		  AND confrelid = to_regclass('multigres.connections')
	) THEN
		ALTER TABLE multigres.migration
			ADD CONSTRAINT migration_connections_fkey FOREIGN KEY (connection_id)
			REFERENCES multigres.connections (connection_id) NOT VALID;
	END IF;
END
$fk$;

CREATE OR REPLACE VIEW multigres.stat_migration AS
SELECT
	m.migration_id,
	m.migration_name,
	c.name::name AS connection_name,
	m.migration_target,
	m.migration_phase,
	m.direction AS active_direction,
	count(r.*) AS total_relations,
	count(r.*) FILTER (WHERE r.srsubstate = 'r') AS ready_relations,
	COALESCE(lag.lag_bytes, 0) AS lag_bytes,
	COALESCE(lag.lag_seconds, 0) AS lag_seconds,
	m.last_error
FROM multigres.migration m
JOIN multigres.connections c USING (connection_id)
LEFT JOIN pg_subscription ps ON ps.subname = 'mt_sub_' || m.migration_id::text
LEFT JOIN pg_subscription_rel r ON r.srsubid = ps.oid
LEFT JOIN LATERAL (
	SELECT
		GREATEST(pg_wal_lsn_diff(pg_current_wal_lsn(), sl.confirmed_flush_lsn), 0)::bigint AS lag_bytes,
		COALESCE(EXTRACT(EPOCH FROM sr.replay_lag), 0)::float8 AS lag_seconds
	FROM pg_replication_slots sl
	LEFT JOIN pg_stat_replication sr ON sr.pid = sl.active_pid
	WHERE sl.slot_name = 'mt_sub_' || m.migration_id::text
) lag ON true
GROUP BY m.migration_id, m.migration_name, c.name, m.migration_target,
	 m.migration_phase, m.direction, m.last_error, lag.lag_bytes, lag.lag_seconds;

GRANT SELECT ON multigres.stat_migration TO PUBLIC;
